    gas3 = mix([('CH4', .72), ('H2', .09), ('N2', .14), ('O2', .02), ('CO2', .03)]); r3 = combustion(gas3, 1.0); Pva = 0.8 * props.sat_T('water', 20, 'Psat_kPa')['value']; Nva = Pva / (101.325 - Pva) * r3['air']
    r3m = combustion(gas3, 1.0, moist=Nva); Pv3, T3 = dew_point(r3m['H2O'], r3m['n_tot'], 101.325); Pv3d, T3d = dew_point(r3['H2O'], r3['n_tot'], 101.325)
    n2_55 = 0.95 * 7.5 * 3.76; rea55 = dict(C6H6=1, O2=0.95 * 7.5, N2=n2_55); pro55 = dict(CO2=5.25, CO=0.75, H2O_g=3, N2=n2_55); q55 = q_out(rea55, 298, pro55, 1000)
    r70 = combustion(single('H2'), 1.2)
    def tad(fuel_key, comp, lam, T_r=298.0):
        r = combustion(single(comp), lam); Hr = Hstate({fuel_key: 1}, T_r) + Hstate({'O2': r['o2_in'], 'N2': r['n2_in']}, T_r); pr = {k: v for k, v in dict(CO2=r['CO2'], H2O_g=r['H2O'], O2=r['O2'], N2=r['N2']).items() if v > 0}
        lo, hi = 298.0, 3200.0
        for _ in range(100):
            mid = (lo + hi) / 2
            if Hstate(pr, mid) > Hr: hi = mid
            else: lo = mid
        return (lo + hi) / 2
    T70 = tad('H2', 'H2', 1.2, 280.0); T158 = tad('C8H18_l', 'C8H18', 1.0); T158b = tad('C8H18_l', 'C8H18', 4.0); T1510 = tad('CH4', 'CH4', 1.5); Tfar = tad('CH4', 'CH4', 1.2)
