        ['13–17', T('cân bằng phương trình cháy octan, AF 24,2', 'balancing the octane equation, AF 24.2'), 'Ex.15-1 (tr.755–756)', '(7.28)–(7.30) (tr.435)', 'Eq.10.8–10.9; Ex.10.2 (tr.754–755)'],
        ['18–26', T('cháy hoàn toàn/không hoàn toàn, lý thuyết, không khí thừa/thiếu, hệ số tương đương, Orsat', 'complete/incomplete, theoretical, excess/deficient air, equivalence ratio, Orsat'), '§15-2 (tr.756–757)', '(7.31)–(7.34) (tr.435–436)', 'Eq.10.10; Ex.10.3–10.4 (tr.755–757)'],
        ['27–32', T('etan: AF 19,3; điểm sương 52,3 °C', 'ethane: AF 19.3; dew point 52.3 °C'), 'Ex.15-2 (tr.757–758); Ex.15-3 (tr.758–760)', '—', '—'],
        ['33–39', T('phân tích cháy ngược octan; nước ngưng ở 25 °C', 'reverse analysis of octane; condensate at 25 °C'), 'Ex.15-4 (tr.760–761)', '—', '—'],
        ['40–52', T('trạng thái chuẩn, h̄_f°, h_C, nhiệt trị HHV/LHV', 'standard state, h̄_f°, h_C, heating values HHV/LHV'), '§15-3 (tr.762–764)', '(7.35)–(7.46); Bảng 7.1; Ex.7.2–7.3 (tr.436–441)', '§10.8, Eq.10.11 (tr.757–758)'],
        ['53–55', T('h_C của octan lỏng; nhiệt lượng kế bom', 'h_C of liquid octane; bomb calorimeter'), 'Ex.15-5 (tr.764–765)', 'Ex.7.3 (HHV/LHV của H₂)', 'Ex.10.5 (tr.758–759)'],
